    host === "localhost" ||
    host === "::1" ||
    host === "[::1]" ||
    host === "metadata.google.internal" ||
    PRIVATE_IPV4_CIDRS.some((re) => re.test(host))
  ) {
    throw new Error(`Blocked SSRF / private-network host: ${host}`);
